"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { 
  Search, Plus, Filter, MoreHorizontal, Calendar, 
  Clock, CheckCircle, AlertCircle, Loader2, ArrowRight,
  User, Flag, X
} from "lucide-react";

// === DATA DUMMY PROKER ===
const initialProkers = [
  { 
    id: 1, 
    title: "Class Meeting Semester Ganjil", 
    sekbid: "Sekbid 3", 
    status: "progress", // todo, progress, done
    date: "15 Jan - 20 Jan", 
    progress: 65, 
    priority: "High", // High, Medium, Low
    pic: "Dimas",
    picColor: "blue"
  },
  { 
    id: 2, 
    title: "Latihan Dasar Kepemimpinan (LDKS)", 
    sekbid: "Inti", 
    status: "todo",
    date: "10 Feb 2026", 
    progress: 0, 
    priority: "High",
    pic: "Raka",
    picColor: "purple"
  },
  { 
    id: 3, 
    title: "Pentas Seni: The Beginning", 
    sekbid: "Sekbid 2", 
    status: "todo",
    date: "Maret 2026", 
    progress: 15, 
    priority: "Medium",
    pic: "Siti",
    picColor: "pink"
  },
  { 
    id: 4, 
    title: "Perbaikan Mading Sekolah", 
    sekbid: "Sekbid 1", 
    status: "done",
    date: "Des 2025", 
    progress: 100, 
    priority: "Low",
    pic: "Budi",
    picColor: "green"
  },
  { 
    id: 5, 
    title: "Donasi Bencana Alam", 
    sekbid: "Sekbid 1", 
    status: "progress",
    date: "Hari Ini", 
    progress: 80, 
    priority: "High",
    pic: "Ahmad",
    picColor: "orange"
  },
];

export default function ProkerPage() {
  const [prokers, setProkers] = useState(initialProkers);
  const [filterSekbid, setFilterSekbid] = useState("Semua");
  const [searchQuery, setSearchQuery] = useState("");
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Filter Logic
  const filteredProkers = prokers.filter((item) => {
    const matchSekbid = filterSekbid === "Semua" ? true : item.sekbid === filterSekbid;
    const matchSearch = item.title.toLowerCase().includes(searchQuery.toLowerCase());
    return matchSekbid && matchSearch;
  });

  // Grouping by Status
  const todos = filteredProkers.filter(p => p.status === 'todo');
  const inProgress = filteredProkers.filter(p => p.status === 'progress');
  const done = filteredProkers.filter(p => p.status === 'done');

  return (
    <div className="relative h-full flex flex-col min-h-screen">
      
      {/* HEADER */}
      <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-8">
        <div>
           <h1 className="text-3xl font-bold font-black text-slate-900 dark:text-white tracking-tight flex items-center gap-3">
             Program Kerja <span className="text-2xl p-2 bg-pink-100 dark:bg-pink-900/30 rounded-full">📅</span>
           </h1>
           <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mt-1">
             Monitoring progres kegiatan dalam tampilan Kanban.
           </p>
        </div>
        
        <button 
          onClick={() => setIsModalOpen(true)}
          className="px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold shadow-lg shadow-blue-600/30 flex items-center gap-2 transition-transform active:scale-95"
        >
           <Plus size={20} /> Buat Proker Baru
        </button>
      </div>

      {/* TOOLBAR */}
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-8 bg-white/50 dark:bg-white/5 p-2 rounded-2xl border border-slate-200 dark:border-white/5 backdrop-blur-sm">
         
         <div className="flex gap-2 overflow-x-auto w-full md:w-auto pb-2 md:pb-0 scrollbar-hide">
            {['Semua', 'Inti', 'Sekbid 1', 'Sekbid 2', 'Sekbid 3'].map((sekbid) => (
               <button
                 key={sekbid}
                 onClick={() => setFilterSekbid(sekbid)}
                 className={`px-4 py-2 rounded-lg text-xs font-bold whitespace-nowrap transition-all border ${
                   filterSekbid === sekbid 
                     ? "bg-white dark:bg-slate-700 text-blue-600 dark:text-white border-blue-100 dark:border-transparent shadow-sm" 
                     : "bg-transparent border-transparent text-slate-500 hover:bg-white/50 dark:hover:bg-white/5"
                 }`}
               >
                 {sekbid}
               </button>
            ))}
         </div>

         <div className="relative flex-1 md:w-72 group w-full">
            <input 
              type="text" 
              placeholder="Cari program kerja..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-white dark:bg-[#0f172a] border border-slate-200 dark:border-white/10 focus:ring-2 focus:ring-blue-500/50 outline-none text-sm font-medium text-slate-700 dark:text-white shadow-sm"
            />
            <Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" />
         </div>
      </div>

      {/* === KANBAN BOARD === */}
      <div className="flex-1 overflow-x-auto pb-8">
         <div className="flex flex-col md:flex-row gap-6 min-w-[1000px] md:min-w-0">
            
            {/* COLUMN 1: AKAN DATANG (TO DO) */}
            <KanbanColumn 
               title="Rencana / Akan Datang" 
               icon={<Calendar size={18} />} 
               count={todos.length}
               color="slate"
            >
               {todos.map((item) => <ProkerCard key={item.id} data={item} />)}
            </KanbanColumn>

            {/* COLUMN 2: SEDANG BERJALAN (IN PROGRESS) */}
            <KanbanColumn 
               title="Sedang Berjalan" 
               icon={<Loader2 size={18} className="animate-spin" />} 
               count={inProgress.length}
               color="blue"
            >
               {inProgress.map((item) => <ProkerCard key={item.id} data={item} />)}
            </KanbanColumn>

            {/* COLUMN 3: SELESAI (DONE) */}
            <KanbanColumn 
               title="Selesai / Terlaksana" 
               icon={<CheckCircle size={18} />} 
               count={done.length}
               color="green"
            >
               {done.map((item) => <ProkerCard key={item.id} data={item} />)}
            </KanbanColumn>

         </div>
      </div>

      {/* MODAL ADD PROKER */}
      <AnimatePresence>
         {isModalOpen && (
            <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
               <motion.div 
                 initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                 onClick={() => setIsModalOpen(false)}
                 className="absolute inset-0 bg-black/60 backdrop-blur-sm"
               />
               <motion.div 
                 initial={{ scale: 0.95, opacity: 0, y: 20 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.95, opacity: 0, y: 20 }}
                 className="relative w-full max-w-lg bg-white dark:bg-[#0f172a] rounded-[2rem] shadow-2xl p-8 border border-slate-200 dark:border-white/10"
               >
                  <div className="flex justify-between items-center mb-6">
                     <h2 className="text-xl font-black text-slate-900 dark:text-white">Proker Baru</h2>
                     <button onClick={() => setIsModalOpen(false)}><X size={24} className="text-slate-400" /></button>
                  </div>
                  <div className="space-y-4">
                     <div>
                        <label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Nama Kegiatan</label>
                        <input type="text" className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 text-sm font-bold dark:text-white" placeholder="Contoh: LDKS 2026" />
                     </div>
                     <div className="grid grid-cols-2 gap-4">
                        <div>
                           <label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Sekbid</label>
                           <select className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 text-sm font-bold dark:text-white">
                              <option>Inti</option>
                              <option>Sekbid 1</option>
                              <option>Sekbid 2</option>
                           </select>
                        </div>
                        <div>
                           <label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Prioritas</label>
                           <select className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 text-sm font-bold dark:text-white">
                              <option>High 🔥</option>
                              <option>Medium</option>
                              <option>Low</option>
                           </select>
                        </div>
                     </div>
                     <button className="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold shadow-lg mt-4">Simpan Proker</button>
                  </div>
               </motion.div>
            </div>
         )}
      </AnimatePresence>

    </div>
  );
}

// === KOMPONEN KOLOM KANBAN ===
function KanbanColumn({ title, icon, count, children, color }: any) {
   const colors: any = {
      slate: "bg-slate-100/50 dark:bg-slate-900/30 border-slate-200/50 dark:border-white/5",
      blue: "bg-blue-50/50 dark:bg-blue-900/10 border-blue-100 dark:border-blue-500/10",
      green: "bg-green-50/50 dark:bg-green-900/10 border-green-100 dark:border-green-500/10",
   }
   const iconColors: any = {
      slate: "text-slate-500",
      blue: "text-blue-500",
      green: "text-green-500",
   }

   return (
      <div className={`flex-1 rounded-[2rem] p-4 border ${colors[color]} flex flex-col min-h-[500px]`}>
         <div className="flex items-center justify-between mb-4 px-2">
            <div className={`flex items-center gap-2 font-bold ${iconColors[color]}`}>
               {icon}
               <span className="text-slate-700 dark:text-slate-200 text-sm">{title}</span>
            </div>
            <span className="px-2.5 py-0.5 rounded-full bg-white dark:bg-white/10 text-xs font-bold text-slate-500 dark:text-slate-400 shadow-sm">
               {count}
            </span>
         </div>
         <div className="space-y-3 flex-1">
            {children}
            {/* Empty Placeholder if no cards */}
            {count === 0 && (
               <div className="h-32 border-2 border-dashed border-slate-200 dark:border-white/5 rounded-2xl flex items-center justify-center text-slate-400 text-xs font-medium">
                  Kosong
               </div>
            )}
         </div>
      </div>
   )
}

// === KOMPONEN KARTU PROKER ===
function ProkerCard({ data }: any) {
   return (
      <motion.div 
         layout
         initial={{ opacity: 0, y: 10 }} 
         animate={{ opacity: 1, y: 0 }}
         whileHover={{ y: -4, boxShadow: "0 10px 30px -10px rgba(0,0,0,0.1)" }}
         className="bg-white dark:bg-[#1e293b] p-4 rounded-2xl border border-slate-100 dark:border-white/5 shadow-sm cursor-grab active:cursor-grabbing group"
      >
         {/* Top Tags */}
         <div className="flex justify-between items-start mb-3">
            <span className="px-2 py-1 rounded-lg bg-slate-50 dark:bg-white/5 text-[10px] font-bold text-slate-500 dark:text-slate-400 border border-slate-100 dark:border-white/5 uppercase tracking-wide">
               {data.sekbid}
            </span>
            <button className="text-slate-300 hover:text-slate-500 dark:hover:text-white transition-colors">
               <MoreHorizontal size={16} />
            </button>
         </div>

         {/* Title */}
         <h3 className="font-bold text-slate-800 dark:text-slate-100 text-sm mb-3 leading-snug group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
            {data.title}
         </h3>

         {/* Progress Bar */}
         <div className="mb-4">
            <div className="flex justify-between text-[10px] font-bold text-slate-400 mb-1">
               <span>Progress</span>
               <span>{data.progress}%</span>
            </div>
            <div className="w-full h-1.5 bg-slate-100 dark:bg-white/5 rounded-full overflow-hidden">
               <div 
                  className={`h-full rounded-full ${
                     data.status === 'done' ? 'bg-green-500' : 
                     data.status === 'progress' ? 'bg-blue-500' : 'bg-slate-300'
                  }`} 
                  style={{ width: `${data.progress}%` }} 
               />
            </div>
         </div>

         {/* Footer Info */}
         <div className="flex items-center justify-between pt-3 border-t border-slate-50 dark:border-white/5">
            <div className="flex items-center gap-2">
               <div className={`w-6 h-6 rounded-full flex items-center justify-center text-[8px] font-bold text-white bg-gradient-to-br from-${data.picColor}-400 to-${data.picColor}-600`}>
                  {data.pic.charAt(0)}
               </div>
               <span className="text-[10px] font-medium text-slate-500 dark:text-slate-400">
                  {data.date}
               </span>
            </div>
            
            {data.priority === 'High' && (
               <div className="flex items-center gap-1 text-[10px] font-bold text-red-500 bg-red-50 dark:bg-red-500/10 px-2 py-0.5 rounded-full">
                  <Flag size={10} fill="currentColor" /> High
               </div>
            )}
         </div>
      </motion.div>
   )
}